in = adsV2NameFinish(checked.copy, nameList, args.language) // KINEO-ADS-MAO-JUIZ-1610 — \"da Perfume Atheeri\" → \"de Perfume Atheeri\"; \"Perfume Atheeri - Fragrâncias\" → \"Perfume Atheeri Fragrâncias\"","  if (finalMain.fixes.length) honestyFixes = [...honestyFixes, ...finalMain.fixes] // KINEO-ADS-MAO-JUIZ-1610","  variants = variants.map((v) => { const f = adsV2NameFinish(v.copy, nameList, args.language); return f.fixes.length ? { ...v, copy: f.copy, honestyFixes: [...(v.honestyFixes ?? []), ...f.fixes] } : v }) // KINEO-ADS-MAO-JUIZ-1610","  return { ok: true, brief, copy: finalMain.copy, dropped: parsed.dropped, attempts, ...(voice ? { voice: { ...voice, namesMissing } } : {}), ...(ad ? { ad } : {}), ...(honestyFixes.length ? { honestyFixes } : {}), ...(variantsInfo ? { variants, variantsInfo } : {}), ...(speechShort ? { speechShort } : {}) } // KINEO-ADS-RETESTE-1510 — speechShort: a fala ficou no piso de antes"]}],"lib/ads/v2LockVision.ts":[{"before":["import { ADS_V2_IN_HAND_PAIR_QUESTION, adsV2InHandJudgeKeys, adsV2InHandJudgeQuestion, adsV2ParseInHandPair, type AdsV2InHandObject } from '@/lib/ads/v2ProductInHand' // KINEO-ADS-MAO-AJUSTE-3-1610","/** KINEO-ADS-PRODUTO-NA-MAO-1610 — o corpo do juiz (puro: o guardião confere modelo do registro, 'high', JSON e a ordem das imagens). */"],"now":["import { ADS_V2_IN_HAND_PAIR_QUESTION, adsV2InHandJudgeKeys, adsV2InHandJudgeQuestion, adsV2ParseInHandPair, type AdsV2InHandObject } from '@/lib/ads/v2ProductInHand' // KINEO-ADS-MAO-AJUSTE-3-1610","import { ADS_V2_IN_HAND_INVENTORY_QUESTION, adsV2InHandFidelityQuestion, adsV2InHandInventoryRule, adsV2InHandTwoStageVerdict, adsV2ParseInHandFidelity, adsV2ParseInHandInventory, type AdsV2InHandBox2d, type AdsV2InHandInventory } from '@/lib/ads/v2ProductInHand' // KINEO-ADS-MAO-JUIZ-1610 — o juiz em 2 etapas","// KINEO-ADS-MAO-JUIZ-1610 — a pessoa extra e o objeto único viraram chaves de DEFEITO (\"extra_person\", \"both_objects\": true = o defeito aparece = reprova): a pergunta de","// KINEO-ADS-MAO-JUIZ-1610 — \"só/apenas\" deu false nas 12 fotos do T1 a6144352. A chamada é a mesma; a pergunta, as chaves e a leitura vêm da lib (adsV2InHandJudgeKeys).","/** KINEO-ADS-PRODUTO-NA-MAO-1610 — o corpo do juiz (puro: o guardião confere modelo do registro, 'high', JSON e a ordem das imagens). */"]},{"before":["export async function adsV2InHandLabelJudge(productUrl: string, sceneUrl: string, doFetch: typeof fetch = fetch, object: AdsV2InHandObject | null = null): Promise<AdsV2InHandVerdict | null> { // KINEO-ADS-PRODUTO-NA-MAO-1610 · KINEO-ADS-MAO-AJUSTE-3-1610 — + object"],"now":["/** KINEO-ADS-MAO-JUIZ-1610 — o modelo do juiz do produto na mão: constante PRÓPRIA (padrão = o de visão do registro; o coordenador troca depois da calibração). */","export const ADS_V2_IN_HAND_JUDGE_MODEL: string = AI_TEXT_MODELS.vision // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — os recortes da fidelidade (servidor: lib/ads/v2ProductInHandCrop.ts): o produto real só com o objeto do plano e o produto da foto gerada. null = sem recorte (as fotos inteiras). */","export type AdsV2InHandCropFn = (a: { sceneUrl: string; objectBox: AdsV2InHandBox2d | null; object: AdsV2InHandObject | null }) => Promise<{ reference: string; generated: string } | null> // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — a resposta crua das 2 etapas (a calibração mostra; o avanço não usa). */","export interface AdsV2InHandJudgeRaw { inventory: unknown; fidelity: unknown; crop: boolean } // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — o corpo do inventário (puro): 1 imagem 'high' ANTES do texto, temperatura 0, JSON, o modelo do juiz. */","export function adsV2InHandInventoryBody(sceneUrl: string): Record<string, unknown> { // KINEO-ADS-MAO-JUIZ-1610","  return { model: ADS_V2_IN_HAND_JUDGE_MODEL, temperature: 0, max_tokens: 700, response_format: { type: 'json_object' }, messages: [{ role: 'user', content: [{ type: 'image_url', image_url: { url: sceneUrl, detail: 'high' } }, { type: 'text', text: ADS_V2_IN_HAND_INVENTORY_QUESTION }] }] } // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — o corpo da fidelidade (puro): \"Image 1 (REFERENCE)\" e \"Image 2 (GENERATED)\" rotuladas, as 2 em 'high', depois a pergunta. */","export function adsV2InHandFidelityBody(referenceUrl: string, generatedUrl: string, object: AdsV2InHandObject | null, crop: boolean): Record<string, unknown> { // KINEO-ADS-MAO-JUIZ-1610","  return { model: ADS_V2_IN_HAND_JUDGE_MODEL, temperature: 0, max_tokens: 150, response_format: { type: 'json_object' }, messages: [{ role: 'user', content: [{ type: 'text', text: 'Image 1 (REFERENCE):' }, { type: 'image_url', image_url: { url: referenceUrl, detail: 'high' } }, { type: 'text', text: 'Image 2 (GENERATED):' }, { type: 'image_url', image_url: { url: generatedUrl, detail: 'high' } }, { type: 'text', text: adsV2InHandFidelityQuestion(object, crop) }] }] } // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","async function inHandVision(doFetch: typeof fetch, key: string, body: Record<string, unknown>): Promise<unknown> { // KINEO-ADS-MAO-JUIZ-1610","  const res = await doFetch('https://api.openai.com/v1/chat/completions', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` }, body: JSON.stringify(body), signal: AbortSignal.timeout(ADS_V2_LOCK_CHECK_TIMEOUT_MS) }) // KINEO-ADS-MAO-JUIZ-1610","  if (!res.ok) return null // KINEO-ADS-MAO-JUIZ-1610","  const j = (await res.json()) as { choices?: { message?: { content?: unknown } }[] } // KINEO-ADS-MAO-JUIZ-1610","  return j?.choices?.[0]?.message?.content ?? null // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — só o inventário de uma foto (a da referência do produto: onde está o frasco e onde está a caixa, para o recorte). null = sem chave/ilegível. Nunca lança. */","export async function adsV2InHandInventoryOf(imageUrl: string, doFetch: typeof fetch = fetch): Promise<AdsV2InHandInventory | null> { // KINEO-ADS-MAO-JUIZ-1610","  const key = process.env.OPENAI_API_KEY // KINEO-ADS-MAO-JUIZ-1610","  if (!key || typeof imageUrl !== 'string' || !(/^https:\\/\\/\\S+$/i.test(imageUrl.trim()) || /^data:image\\/(?:jpeg|jpg|png|webp);base64,/.test(imageUrl.trim()))) return null // KINEO-ADS-MAO-JUIZ-1610","  try { return adsV2ParseInHandInventory(await inHandVision(doFetch, key, adsV2InHandInventoryBody(imageUrl.trim()))) } catch { return null } // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","/**"," * KINEO-ADS-PRODUTO-NA-MAO-1610 — o produto do still bate com a foto real? null = não deu para conferir. Nunca lança."," * KINEO-ADS-MAO-JUIZ-1610 — EM 2 ETAPAS: (i) o INVENTÁRIO da foto gerada (o que se vê, com caixas; o código aplica a regra do plano) e (ii) a FIDELIDADE com o"," * KINEO-ADS-MAO-JUIZ-1610 — recorte do produto real ao lado do recorte do produto gerado (crop; sem recorte = as fotos inteiras), atributo por atributo."," * KINEO-ADS-MAO-JUIZ-1610 — \"unsure\" só registra. Inventário ilegível = null (a foto segue). A calibração (POST /api/admin/ads-judge-calibrate) chama ESTA"," * KINEO-ADS-MAO-JUIZ-1610 — MESMA função com sink (a resposta crua) e o mesmo crop do avanço."," */","export async function adsV2InHandLabelJudge(productUrl: string, sceneUrl: string, doFetch: typeof fetch = fetch, object: AdsV2InHandObject | null = null, sink?: (raw: AdsV2InHandJudgeRaw) => void, crop?: AdsV2InHandCropFn): Promise<AdsV2InHandVerdict | null> { // KINEO-ADS-MAO-JUIZ-1610 — 2 etapas + sink + crop"]},{"before":["  const ok = (u: unknown): u is string => typeof u === 'string' && /^https:\\/\\/\\S+$/i.test(u.trim()) // KINEO-ADS-PRODUTO-NA-MAO-1610"],"now":["  const ok = (u: unknown): u is string => typeof u === 'string' && (/^https:\\/\\/\\S+$/i.test(u.trim()) || /^data:image\\/(?:jpeg|jpg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(u.trim())) // KINEO-ADS-PRODUTO-NA-MAO-1610 · KINEO-ADS-MAO-JUIZ-1610 — + data:image (a calibração com as fotos salvas; o avanço só passa https)"]},{"before":["  try { // KINEO-ADS-PRODUTO-NA-MAO-1610","    const res = await doFetch('https://api.openai.com/v1/chat/completions', { // KINEO-ADS-PRODUTO-NA-MAO-1610","      method: 'POST', // KINEO-ADS-PRODUTO-NA-MAO-1610","      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` }, // KINEO-ADS-PRODUTO-NA-MAO-1610","      body: JSON.stringify(adsV2InHandLabelBody(productUrl.trim(), sceneUrl.trim(), object)), // KINEO-ADS-PRODUTO-NA-MAO-1610 · KINEO-ADS-MAO-AJUSTE-3-1610 — + object","      signal: AbortSignal.timeout(ADS_V2_LOCK_CHECK_TIMEOUT_MS), // KINEO-ADS-PRODUTO-NA-MAO-1610 — o prazo da conferência em 'high'","    }) // KINEO-ADS-PRODUTO-NA-MAO-1610","    if (!res.ok) return null // KINEO-ADS-PRODUTO-NA-MAO-1610","    const j = (await res.json()) as { choices?: { message?: { content?: unknown } }[] } // KINEO-ADS-PRODUTO-NA-MAO-1610","    return adsV2ParseInHandVerdict(j?.choices?.[0]?.message?.content ?? null, adsV2InHandJudgeKeys(object)) // KINEO-ADS-PRODUTO-NA-MAO-1610 · KINEO-ADS-MAO-AJUSTE-3-1610 — as chaves desta conferência (sem \"people\" = ilegível)","  } catch { // KINEO-ADS-PRODUTO-NA-MAO-1610","    return null // KINEO-ADS-PRODUTO-NA-MAO-1610","  } // KINEO-ADS-PRODUTO-NA-MAO-1610","} // KINEO-ADS-PRODUTO-NA-MAO-1610"],"now":["  const tell = (raw: AdsV2InHandJudgeRaw) => { if (sink) { try { sink(raw) } catch { /* a calibração nunca derruba o juiz */ } } } // KINEO-ADS-MAO-JUIZ-1610","  try { // KINEO-ADS-MAO-JUIZ-1610","    const invRaw = await inHandVision(doFetch, key, adsV2InHandInventoryBody(sceneUrl.trim())) // KINEO-ADS-MAO-JUIZ-1610 — (i) inventário","    const inv = adsV2ParseInHandInventory(invRaw) // KINEO-ADS-MAO-JUIZ-1610","    if (!inv) { tell({ inventory: invRaw, fidelity: null, crop: false }); return null } // KINEO-ADS-MAO-JUIZ-1610","    const rule = adsV2InHandInventoryRule(inv, object) // KINEO-ADS-MAO-JUIZ-1610","    const crops = crop ? await crop({ sceneUrl: sceneUrl.trim(), objectBox: rule.objectBox, object }).catch(() => null) : null // KINEO-ADS-MAO-JUIZ-1610","    const cropOk = !!crops && ok(crops.reference) && ok(crops.generated) // KINEO-ADS-MAO-JUIZ-1610","    const fidRaw = await inHandVision(doFetch, key, adsV2InHandFidelityBody(cropOk ? crops!.reference : productUrl.trim(), cropOk ? crops!.generated : sceneUrl.trim(), object, cropOk)).catch(() => null) // KINEO-ADS-MAO-JUIZ-1610 — (ii) fidelidade","    tell({ inventory: invRaw, fidelity: fidRaw, crop: cropOk }) // KINEO-ADS-MAO-JUIZ-1610","    return adsV2InHandTwoStageVerdict(inv, adsV2ParseInHandFidelity(fidRaw), object, cropOk) // KINEO-ADS-MAO-JUIZ-1610","  } catch { // KINEO-ADS-MAO-JUIZ-1610","    return null // KINEO-ADS-MAO-JUIZ-1610","  } // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610"]}],"lib/ads/v2ProductInHand.ts":[{"before":["// KINEO-ADS-MAO-AJUSTE-3-1610 — rótulo vira uma mão inclinando o objeto; borrifo cortado em 2,3 s; packshot + cartão 4 s (era 5,5) e os planos de gente ganham o tempo.","//"],"now":["// KINEO-ADS-MAO-AJUSTE-3-1610 — rótulo vira uma mão inclinando o objeto; borrifo cortado em 2,3 s; packshot + cartão 4 s (era 5,5) e os planos de gente ganham o tempo.","// KINEO-ADS-MAO-JUIZ-1610 — o T1 da 3ª rodada (docs/RESULTADO-T1-MAO-AJUSTE-3-2026-10-16.md, pedido a6144352): \"only_object\" reprovou as 12 fotos (7 estavam certas)","// KINEO-ADS-MAO-JUIZ-1610 — e os 4 planos de gente viraram packshot; \"people\" aprovou um homem desfocado na janela. Agora as duas são chaves de DEFEITO","// KINEO-ADS-MAO-JUIZ-1610 — (\"both_objects\", \"extra_person\": true = o defeito aparece) e reprovação SÓ nelas usa a melhor foto (nunca o packshot); o packshot","// KINEO-ADS-MAO-JUIZ-1610 — fica para o rótulo/produto errado, no máximo 1 plano de gente por anúncio.","//"]},{"before":["export const ADS_V2_IN_HAND_JUDGE_QUESTION = 'The FIRST image is the real product photo. The SECOND image is a generated photo of a person with that product. Be strict: compare the product in the SECOND image with the FIRST one and answer each item with true or false; when in doubt, answer false. \"name\": the brand name and the logo, where they are visible, are the same words and the same logo (small text may be blurry, but it must not turn into a different word or a different logo). \"colors\": every visible part of the product has the same colors as in the FIRST image, including the body of the bottle or the package and the color of any liquid inside. \"material\": every part keeps the same material and finish as in the FIRST image (clear glass stays clear and see-through, matte cardboard stays matte cardboard); a black, opaque or painted body where the FIRST image shows clear glass is false. \"shape\": the shape and the proportions of the packaging are the same. \"count\": the SECOND image shows no more product items than the FIRST image (no extra bottle, box, package or duplicate). \"hands\": the hands look natural, with five fingers, and nothing passes through the product. \"one_product\": every product item in the SECOND image is part of the product of the FIRST image; no different product appears. Answer only with JSON with the keys \"name\", \"colors\", \"material\", \"shape\", \"count\", \"hands\" and \"one_product\", each one true or false.' // KINEO-ADS-MAO-AJUSTE-1610 — mais rígida: cor do corpo e do líquido, material, quantidade (no T1 aprovou um frasco preto inventado)"],"now":["export const ADS_V2_IN_HAND_JUDGE_QUESTION = 'The FIRST image is the real product photo. The SECOND image is a generated photo of a person with that product. Be strict: compare the product in the SECOND image with the FIRST one and answer each item with true or false. \"name\": the brand name and the logo, where they are visible, are the same words and the same logo (small text may be blurry, but it must not turn into a different word or a different logo). \"colors\": every visible part of the product has the same colors as in the FIRST image, including the body of the bottle or the package and the color of any liquid inside. \"material\": every part keeps the same material and finish as in the FIRST image (clear glass stays clear and see-through, matte cardboard stays matte cardboard); a black, opaque or painted body where the FIRST image shows clear glass is false. \"shape\": the shape and the proportions of the packaging are the same. \"count\": the SECOND image shows no more product items than the FIRST image (no extra bottle, box, package or duplicate). \"hands\": the hands look natural, with five fingers, and nothing passes through the product. \"one_product\": every product item in the SECOND image is part of the product of the FIRST image; no different product appears. Answer only with JSON with the keys \"name\", \"colors\", \"material\", \"shape\", \"count\", \"hands\" and \"one_product\", each one true or false.' // KINEO-ADS-MAO-AJUSTE-1610 — mais rígida: cor do corpo e do líquido, material, quantidade (no T1 aprovou um frasco preto inventado) · KINEO-ADS-MAO-JUIZ-1610 — sem \"when in doubt, answer false\" (puxava tudo para reprovar; o juiz agora é o de 2 etapas abaixo)"]},{"before":["export const ADS_V2_IN_HAND_JUDGE_PEOPLE = '\"people\": the SECOND image shows exactly one person (or only the hands of that one person); there is no other person anywhere: nobody in the background, and no other face, eye, hand or body part cut off at the edge of the frame. Any extra person or cut-off body part is false.' // KINEO-ADS-MAO-AJUSTE-3-1610","/** KINEO-ADS-MAO-AJUSTE-3-1610 — a pergunta do objeto único (foto com frasco + caixa): os dois juntos = reprova. */"],"now":["/** KINEO-ADS-MAO-JUIZ-1610 — virou chave de DEFEITO (\"extra_person\": true = há mais alguém): a de \"pessoa certa\" aprovou o homem desfocado na janela (foto 5 do T1 a6144352). */","export const ADS_V2_IN_HAND_JUDGE_PEOPLE = '\"extra_person\": Is there any OTHER person in the SECOND image besides the one main person with the product? Look at the whole frame: a blurred or out-of-focus person in the background, a person seen through a window or a glass door, a person reflected in a mirror, window or glass, and any other face, eye, hand, arm or body part entering from the edge of the frame. Answer true if you can see any extra person or extra body part, even a small or blurry one; answer false if the main person is the only one.' // KINEO-ADS-MAO-JUIZ-1610 — era \"people\" (true = certo)","/** KINEO-ADS-MAO-AJUSTE-3-1610 — a pergunta do objeto único (foto com frasco + caixa): os dois juntos = reprova. */","/** KINEO-ADS-MAO-JUIZ-1610 — virou chave de DEFEITO (\"both_objects\": true = frasco E caixa na foto): \"only_object\" (só/apenas) deu false nas 12 fotos do T1 a6144352, 7 delas certas. */"]},{"before":["  bottle: '\"only_object\": the FIRST image shows a bottle together with its box, but this shot must show ONLY the bottle: true only if the bottle appears and the box does not appear anywhere in the SECOND image; both together is false.', // KINEO-ADS-MAO-AJUSTE-3-1610","  box: '\"only_object\": the FIRST image shows a bottle together with its box, but this shot must show ONLY the box: true only if the box appears and the bottle does not appear anywhere in the SECOND image outside its closed box; both together is false.', // KINEO-ADS-MAO-AJUSTE-3-1610","} // KINEO-ADS-MAO-AJUSTE-3-1610"],"now":["  bottle: '\"both_objects\": Is there BOTH a bottle (the product container) AND a separate box (the carton package) visible in the SECOND image? Answer true only if you can see both objects; if you see only the bottle, answer false.', // KINEO-ADS-MAO-JUIZ-1610 — era \"only_object\" (true = certo)","  box: '\"both_objects\": Is there BOTH a bottle (the product container) AND a separate box (the carton package) visible in the SECOND image? Answer true only if you can see both objects; if you see only the box, answer false.', // KINEO-ADS-MAO-JUIZ-1610 — era \"only_object\" (true = certo)","} // KINEO-ADS-MAO-AJUSTE-3-1610","/** KINEO-ADS-MAO-JUIZ-1610 — as chaves de DEFEITO: true = o defeito aparece (reprova); false = passa. As outras chaves continuam true = certo. */","export const ADS_V2_IN_HAND_DEFECT_KEYS: readonly string[] = ['extra_person', 'both_objects'] // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — a frase que separa as perguntas de defeito das de fidelidade (na pergunta, antes delas). */","export const ADS_V2_IN_HAND_JUDGE_DEFECT_INTRO = 'The next items ask about DEFECTS: answer true only if you can actually see the defect, otherwise answer false.' // KINEO-ADS-MAO-JUIZ-1610"]},{"before":["  return [...ADS_V2_IN_HAND_JUDGE_KEYS, 'people', ...(object === 'bottle' || object === 'box' ? ['only_object'] : [])] // KINEO-ADS-MAO-AJUSTE-3-1610"],"now":["  return [...ADS_V2_IN_HAND_JUDGE_KEYS, 'extra_person', ...(object === 'bottle' || object === 'box' ? ['both_objects'] : [])] // KINEO-ADS-MAO-AJUSTE-3-1610 · KINEO-ADS-MAO-JUIZ-1610 — chaves de defeito (eram \"people\" e \"only_object\")"]},{"before":["  const items = [ADS_V2_IN_HAND_JUDGE_PEOPLE, ...(object === 'bottle' || object === 'box' ? [ADS_V2_IN_HAND_JUDGE_OBJECT[object]] : [])] // KINEO-ADS-MAO-AJUSTE-3-1610"],"now":["  const items = [ADS_V2_IN_HAND_JUDGE_DEFECT_INTRO, ADS_V2_IN_HAND_JUDGE_PEOPLE, ...(object === 'bottle' || object === 'box' ? [ADS_V2_IN_HAND_JUDGE_OBJECT[object]] : [])] // KINEO-ADS-MAO-AJUSTE-3-1610 · KINEO-ADS-MAO-JUIZ-1610 — + a frase dos defeitos"]},{"before":["export interface AdsV2InHandVerdict { ok: boolean; fails: string[] }"],"now":["export interface AdsV2InHandVerdict { ok: boolean; fails: string[]; unsure?: string[]; crop?: boolean } // KINEO-ADS-MAO-JUIZ-1610 — + unsure (\"não sei\": só log) e crop (a fidelidade comparou os recortes)","","// ── KINEO-ADS-MAO-JUIZ-1610 — O JUIZ EM 2 ETAPAS (docs/PESQUISA-SEM-ERRO-PRODUTO-NA-MAO-2026-10-16.md, (a) regras 1, 2, 3, 6 e (c) prioridade 1) ─────────","// KINEO-ADS-MAO-JUIZ-1610 — (i) INVENTÁRIO: o modelo lista o que VÊ (produtos e pessoas, cada um com box_2d e \"yes\"/\"unsure\"); nada de \"só/apenas\", nada de","// KINEO-ADS-MAO-JUIZ-1610 — negação. O CÓDIGO aplica a regra do plano (frasco E caixa no plano de um objeto = defeito; mais de uma pessoa = defeito).","// KINEO-ADS-MAO-JUIZ-1610 — (ii) FIDELIDADE: o recorte do produto gerado ao lado do recorte do produto real, rotulados, atributo por atributo (\"yes\"/\"no\"/\"unsure\").","// KINEO-ADS-MAO-JUIZ-1610 — \"unsure\" vai para o log e NUNCA reprova; a frase \"when in doubt, answer false\" saiu.","export type AdsV2InHandTri = 'yes' | 'no' | 'unsure' // KINEO-ADS-MAO-JUIZ-1610","export type AdsV2InHandBox2d = [number, number, number, number] // KINEO-ADS-MAO-JUIZ-1610 — [ymin, xmin, ymax, xmax], de 0 a 1000","export interface AdsV2InHandInventory { // KINEO-ADS-MAO-JUIZ-1610","  products: { type: 'bottle' | 'box' | 'other'; box: AdsV2InHandBox2d | null; visible: 'yes' | 'unsure' }[] // KINEO-ADS-MAO-JUIZ-1610","  people: { box: AdsV2InHandBox2d | null; visible: 'yes' | 'unsure' }[] // KINEO-ADS-MAO-JUIZ-1610","  hands: AdsV2InHandTri // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — a pergunta do inventário (1 imagem). Só presença e posição: o código decide. */","export const ADS_V2_IN_HAND_INVENTORY_QUESTION = 'Image 1 is a photo. List what you can see in it. \"products\": every product item you can see — a bottle (a perfume or cosmetic bottle, jar or flask), a box (a carton package) or another product item — each one with \"type\" (\"bottle\", \"box\" or \"other\"), \"box_2d\" as [ymin, xmin, ymax, xmax] from 0 to 1000, and \"visible\" (\"yes\", or \"unsure\" when you cannot tell). A bottle seen through the window of its own box counts as part of that box. \"people\": every distinct person you can see, each person once with one box around all of their visible body parts — including a blurred or out-of-focus person in the background, a person seen through a window or glass, a person reflected in a mirror or glass, and a person whose face, hand or arm enters from the edge of the frame — each one with \"box_2d\" and \"visible\" (\"yes\" or \"unsure\"). The hands of the person holding the product belong to that same person. \"hands\": do the visible hands look natural, with five fingers and nothing passing through the product? Answer \"yes\", \"no\" or \"unsure\". Answer with JSON: {\"products\": [], \"people\": [], \"hands\": \"\"}.' // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — o nome de cada objeto do plano na pergunta de fidelidade. */","export const ADS_V2_IN_HAND_OBJECT_NAME: Readonly<Record<AdsV2InHandObject | 'single', string>> = { bottle: 'the bottle', box: 'the box', single: 'the product' } // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — as chaves da fidelidade (cada uma \"yes\" / \"no\" / \"unsure\"). */","export const ADS_V2_IN_HAND_FIDELITY_KEYS: readonly string[] = ['name', 'colors', 'material', 'shape'] // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — a pergunta da fidelidade: crop = os dois recortes; senão as fotos inteiras (o recorte falhou), sempre rotuladas. Pura. */","export function adsV2InHandFidelityQuestion(object: AdsV2InHandObject | null, crop: boolean): string { // KINEO-ADS-MAO-JUIZ-1610","  const it = ADS_V2_IN_HAND_OBJECT_NAME[object ?? 'single'] // KINEO-ADS-MAO-JUIZ-1610","  const intro = crop // KINEO-ADS-MAO-JUIZ-1610","    ? `Image 1 (REFERENCE) is a crop of ${it} from the real product photo. Image 2 (GENERATED) is a crop of ${it} from a generated photo. Compare Image 2 with Image 1, one attribute at a time.` // KINEO-ADS-MAO-JUIZ-1610","    : `Image 1 (REFERENCE) is the real product photo. Image 2 (GENERATED) is a generated photo of a person with the product. Compare ${it} in Image 2 with ${it} in Image 1, one attribute at a time.` // KINEO-ADS-MAO-JUIZ-1610","  return intro + ' Answer each attribute with \"yes\", \"no\" or \"unsure\". \"name\": the brand words and the logo visible in Image 2 are the same as in Image 1 (small text may be blurry; it must not read as a different word or a different logo). \"colors\": the colors in Image 2 are the same as in Image 1, including the body of the bottle or package and the color of any liquid inside. \"material\": the material and finish in Image 2 are the same as in Image 1 (clear glass stays clear and see-through; matte cardboard stays matte cardboard). \"shape\": the shape and the proportions in Image 2 are the same as in Image 1. Answer only with JSON with the keys \"name\", \"colors\", \"material\" and \"shape\".' // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","const tri = (v: unknown): AdsV2InHandTri | null => (v === 'yes' || v === 'no' || v === 'unsure' ? v : v === true ? 'yes' : v === false ? 'no' : null) // KINEO-ADS-MAO-JUIZ-1610","const box2d = (v: unknown): AdsV2InHandBox2d | null => (Array.isArray(v) && v.length === 4 && v.every((n) => typeof n === 'number' && Number.isFinite(n)) && v[2] > v[0] && v[3] > v[1] ? [v[0], v[1], v[2], v[3]].map((n) => Math.max(0, Math.min(1000, n))) as AdsV2InHandBox2d : null) // KINEO-ADS-MAO-JUIZ-1610","const jsonOf = (raw: unknown): Record<string, unknown> | null => { let j: unknown = raw; if (typeof raw === 'string') { try { j = JSON.parse(raw) } catch { return null } } return j && typeof j === 'object' && !Array.isArray(j) ? (j as Record<string, unknown>) : null } // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — a resposta do inventário (pura): sem \"products\"/\"people\" em lista = null (ilegível); item torto é ignorado. */","export function adsV2ParseInHandInventory(raw: unknown): AdsV2InHandInventory | null { // KINEO-ADS-MAO-JUIZ-1610","  const o = jsonOf(raw) // KINEO-ADS-MAO-JUIZ-1610","  if (!o || !Array.isArray(o.products) || !Array.isArray(o.people)) return null // KINEO-ADS-MAO-JUIZ-1610","  const vis = (v: unknown): 'yes' | 'unsure' | null => (v === 'yes' || v === true ? 'yes' : v === 'unsure' ? 'unsure' : null) // KINEO-ADS-MAO-JUIZ-1610","  const products: AdsV2InHandInventory['products'] = [] // KINEO-ADS-MAO-JUIZ-1610","  for (const p of o.products as unknown[]) { const x = p as { type?: unknown; box_2d?: unknown; visible?: unknown } | null; const v = x ? vis(x.visible ?? 'yes') : null; if (x && v && (x.type === 'bottle' || x.type === 'box' || x.type === 'other')) products.push({ type: x.type, box: box2d(x.box_2d), visible: v }) } // KINEO-ADS-MAO-JUIZ-1610","  const people: AdsV2InHandInventory['people'] = [] // KINEO-ADS-MAO-JUIZ-1610","  for (const p of o.people as unknown[]) { const x = p as { box_2d?: unknown; visible?: unknown } | null; const v = x ? vis(x.visible ?? 'yes') : null; if (x && v) people.push({ box: box2d(x.box_2d), visible: v }) } // KINEO-ADS-MAO-JUIZ-1610","  return { products, people, hands: tri(o.hands) ?? 'unsure' } // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","const area = (b: AdsV2InHandBox2d | null): number => (b ? (b[2] - b[0]) * (b[3] - b[1]) : 0) // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — a regra do plano sobre o inventário (pura): os defeitos, o \"não sei\" e a caixa do objeto do plano (para o recorte). */","export function adsV2InHandInventoryRule(inv: AdsV2InHandInventory, object: AdsV2InHandObject | null): { fails: string[]; unsure: string[]; objectBox: AdsV2InHandBox2d | null; seen: string[] } { // KINEO-ADS-MAO-JUIZ-1610","  const yes = inv.products.filter((p) => p.visible === 'yes') // KINEO-ADS-MAO-JUIZ-1610","  const fails: string[] = [] // KINEO-ADS-MAO-JUIZ-1610","  const unsure = [...inv.products.filter((p) => p.visible === 'unsure').map((p) => 'product:' + p.type), ...inv.people.filter((p) => p.visible === 'unsure').map(() => 'person'), ...(inv.hands === 'unsure' ? ['hands'] : [])] // KINEO-ADS-MAO-JUIZ-1610","  if (object && yes.filter((p) => p.type === object).length > 1) fails.push('count') // KINEO-ADS-MAO-JUIZ-1610 — o objeto do plano em dobro","  if (inv.hands === 'no') fails.push('hands') // KINEO-ADS-MAO-JUIZ-1610","  if (inv.people.filter((p) => p.visible === 'yes').length > 1) fails.push('extra_person') // KINEO-ADS-MAO-JUIZ-1610","  if (object && yes.some((p) => p.type === 'bottle') && yes.some((p) => p.type === 'box')) fails.push('both_objects') // KINEO-ADS-MAO-JUIZ-1610","  const wanted = yes.filter((p) => (object ? p.type === object : p.type !== 'other') && p.box).sort((a, b) => area(b.box) - area(a.box)) // KINEO-ADS-MAO-JUIZ-1610","  const seen = yes.map((p) => p.type) // KINEO-ADS-MAO-JUIZ-1610","  if (object && !seen.includes(object)) unsure.push('object_missing:' + object) // KINEO-ADS-MAO-JUIZ-1610 — o plano pedia este objeto e ele não apareceu: log (a foto continua sendo do produto do cliente)","  return { fails, unsure, objectBox: wanted[0]?.box ?? null, seen } // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — a resposta da fidelidade (pura): cada chave \"yes\"/\"no\"/\"unsure\" (true/false também valem); chave faltando = null (ilegível). */","export function adsV2ParseInHandFidelity(raw: unknown): Record<string, AdsV2InHandTri> | null { // KINEO-ADS-MAO-JUIZ-1610","  const o = jsonOf(raw) // KINEO-ADS-MAO-JUIZ-1610","  if (!o) return null // KINEO-ADS-MAO-JUIZ-1610","  const out: Record<string, AdsV2InHandTri> = {} // KINEO-ADS-MAO-JUIZ-1610","  for (const k of ADS_V2_IN_HAND_FIDELITY_KEYS) { const t = tri(o[k]); if (!t) return null; out[k] = t } // KINEO-ADS-MAO-JUIZ-1610","  return out // KINEO-ADS-MAO-JUIZ-1610","} // KINEO-ADS-MAO-JUIZ-1610","/** KINEO-ADS-MAO-JUIZ-1610 — o veredito das 2 etapas (puro). Inventário ilegível = null (a foto segue, a regra de sempre do juiz fora do ar). Fidelidade"," *  ilegível = só o inventário decide (e \"fidelity\" vai para o \"não sei\"). \"no\" reprova; \"unsure\" só registra. */","export function adsV2InHandTwoStageVerdict(inv: AdsV2InHandInventory | null, fidelity: Record<string, AdsV2InHandTri> | null, object: Ad