/** O texto de ANTES desta camada (LF). Lança se um bloco dela não estiver lá exatamente uma vez. */
export function semMaoJuiz1610(rel, text) {
  let s = desfazJuizGrade1610(rel, String(text)) // KINEO-JUIZ-GRADE-1610 — a grade do juiz sai primeiro (já devolve LF)
  const hunks = DESFAZ[rel]
  if (!hunks) return s
  for (const h of hunks) {
    const now = h.now.join('\n')
    const parts = s.split(now)
    if (parts.length !== 2) throw new Error('semMaoJuiz1610: ' + rel + ' mudou fora desta camada (' + (parts.length - 1) + 'x: ' + now.slice(0, 60) + ')')
    s = parts.join(h.before.join('\n'))
  }
  return s
}
